package com.portfolio.catalogservice.api; import com.portfolio.catalogservice.domain.Product; import com.portfolio.catalogservice.repo.ProductRepository; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*; @RestController @RequestMapping("/api/v1/products") public class ProductController { private final ProductRepository repo; public ProductController(ProductRepository r){repo=r;} @GetMapping Page<Product> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return repo.findAll(PageRequest.of(page,Math.min(100,size)));} @GetMapping("/{id}") Product get(@PathVariable long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));} @PostMapping ResponseEntity<Product> create(@Valid @RequestBody ProductRequest r){if(repo.existsBySkuIgnoreCase(r.sku())) throw new ResponseStatusException(HttpStatus.CONFLICT,"SKU exists"); Product e=new Product();e.setName(r.name());e.setDescription(r.description());e.setPrice(r.price());e.setSku(r.sku());return ResponseEntity.status(201).body(repo.save(e));} }